        address inputToken,
        uint256 maxIn,
        uint256 exactOut,
        bytes calldata swapData
    ) external {
        ERC20(inputToken).safeTransferFrom(msg.sender, address(this), maxIn);
        OdosSwapUtils.executeSwapOperation(router, inputToken, address(0), maxIn, exactOut, swapData);
    }
}

