// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title DeterministicVaultSelector
 * @notice Library for selecting vaults based on allocation deltas for optimal rebalancing
 * @dev Used by DStake Router V2 to deterministically select top under/over allocated vaults
 *      during deposits and withdrawals. Provides gas-efficient alternative to weighted random
 *      selection by using partial sort algorithm for predictable vault selection.
 *
 * Key Features:
 * - Allocation-based prioritization: Selects most misallocated vaults to converge toward targets
 * - Partial sort algorithm: O(k*n) complexity optimized for selecting 1-3 vaults from 5-10 total
 */
library DeterministicVaultSelector {
    /// @dev Error thrown when arrays have mismatched lengths
    error ArrayLengthMismatch();

    /// @dev Error thrown when no items are available for selection
    error NoItemsAvailable();

    /// @dev Error thrown when requesting more items than available
    error InsufficientItems();

    /// @dev Error thrown when selection count is zero
    error InvalidSelectionCount();

    /**
     * @dev Struct to hold vault data during sorting operations
     */
    struct VaultData {
        address vault;
        uint256 delta;
        uint256 originalIndex;
    }

    /**
     * @notice Calculates underallocation amounts for deposit weight calculation
     * @dev Underallocation = max(0, targetBps - currentBps) for underweight vaults
     * @param currentAllocations Array of current allocations in basis points
     * @param targetAllocations Array of target allocations in basis points
     * @return underallocations Array of calculated underallocations
     */
    function calculateUnderallocations(
        uint256[] memory currentAllocations,
        uint256[] memory targetAllocations
    ) internal pure returns (uint256[] memory underallocations) {
        if (currentAllocations.length != targetAllocations.length) {
            revert ArrayLengthMismatch();
        }

        underallocations = new uint256[](currentAllocations.length);

        for (uint256 i = 0; i < currentAllocations.length; i++) {
            // Underallocation = max(0, target - current) for underweight vaults
            if (targetAllocations[i] > currentAllocations[i]) {
                underallocations[i] = targetAllocations[i] - currentAllocations[i];
            } else {
                underallocations[i] = 0;
            }
        }

        return underallocations;
    }

    /**
     * @notice Calculates overallocation amounts for withdrawal weight calculation
     * @dev Overallocation = max(0, currentBps - targetBps) for overweight vaults
     * @param currentAllocations Array of current allocations in basis points
     * @param targetAllocations Array of target allocations in basis points
     * @return overallocations Array of calculated overallocations
     */
    function calculateOverallocations(
        uint256[] memory currentAllocations,
        uint256[] memory targetAllocations
    ) internal pure returns (uint256[] memory overallocations) {
        if (currentAllocations.length != targetAllocations.length) {
            revert ArrayLengthMismatch();
        }

        overallocations = new uint256[](currentAllocations.length);

        for (uint256 i = 0; i < currentAllocations.length; i++) {
            // Overallocation = max(0, current - target) for overweight vaults
            if (currentAllocations[i] > targetAllocations[i]) {
                overallocations[i] = currentAllocations[i] - targetAllocations[i];
            } else {
                overallocations[i] = 0;
            }
        }

        return overallocations;
    }

    /**
     * @notice Selects top X most underallocated vaults for deposit operations
     * @dev Uses partial sort algorithm to find vaults with highest (target - current) deltas
     * @param vaults Array of vault addresses to select from
     * @param currentBps Array of current allocations in basis points
     * @param targetBps Array of target allocations in basis points
     * @param count Number of vaults to select (must be <= vaults.length)
     * @return selectedVaults Array of selected vault addresses
     * @return selectedIndices Array of indices of selected vaults in original array
     */
    function selectTopUnderallocated(
        address[] memory vaults,
        uint256[] memory currentBps,
        uint256[] memory targetBps,
        uint256 count
    ) internal pure returns (address[] memory selectedVaults, uint256[] memory selectedIndices) {
        if (vaults.length != currentBps.length || currentBps.length != targetBps.length) {
            revert ArrayLengthMismatch();
        }

        if (vaults.length == 0) {
            revert NoItemsAvailable();
        }

        if (count == 0) {
            revert InvalidSelectionCount();
        }

        if (count > vaults.length) {
            revert InsufficientItems();
        }

        // Calculate underallocations
        uint256[] memory underallocations = calculateUnderallocations(currentBps, targetBps);

        // Check if any underallocations exist
        bool hasUnderallocations = false;
        for (uint256 i = 0; i < underallocations.length; i++) {
            if (underallocations[i] > 0) {
                hasUnderallocations = true;
                break;
            }
        }

        // If no underallocations, select first count vaults deterministically
        if (!hasUnderallocations) {
            selectedVaults = new address[](count);
            selectedIndices = new uint256[](count);
            for (uint256 i = 0; i < count; i++) {
                selectedVaults[i] = vaults[i];
                selectedIndices[i] = i;
            }
            return (selectedVaults, selectedIndices);
        }

        // Use partial sort to find top count underallocated vaults
        return _selectTopVaultsByDelta(vaults, underallocations, count);
    }

    /**
     * @notice Selects top X most overallocated vaults for withdrawal operations
     * @dev Uses partial sort algorithm to find vaults with highest (current - target) deltas
     * @param vaults Array of vault addresses to select from
     * @param currentBps Array of current allocations in basis points
     * @param targetBps Array of target allocations in basis points
     * @param count Number of vaults to select (must be <= vaults.length)
     * @return selectedVaults Array of selected vault addresses
     * @return selectedIndices Array of indices of selected vaults in original array
     */
    function selectTopOverallocated(
        address[] memory vaults,
        uint256[] memory currentBps,
        uint256[] memory targetBps,
        uint256 count
    ) internal pure returns (address[] memory selectedVaults, uint256[] memory selectedIndices) {
        if (vaults.length != currentBps.length || currentBps.length != targetBps.length) {
            revert ArrayLengthMismatch();
        }

        if (vaults.length == 0) {
            revert NoItemsAvailable();
        }

        if (count == 0) {
            revert InvalidSelectionCount();
        }

        if (count > vaults.length) {
            revert InsufficientItems();
        }

        // Calculate overallocations
        uint256[] memory overallocations = calculateOverallocations(currentBps, targetBps);

        // Check if any overallocations exist
        bool hasOverallocations = false;
        for (uint256 i = 0; i < overallocations.length; i++) {
            if (overallocations[i] > 0) {
                hasOverallocations = true;
                break;
            }
        }

        // If no overallocations, select first count vaults deterministically
        if (!hasOverallocations) {
            selectedVaults = new address[](count);
            selectedIndices = new uint256[](count);
            for (uint256 i = 0; i < count; i++) {
                selectedVaults[i] = vaults[i];
                selectedIndices[i] = i;
            }
            return (selectedVaults, selectedIndices);
        }

        // Use partial sort to find top count overallocated vaults
        return _selectTopVaultsByDelta(vaults, overallocations, count);
    }

    /**
     * @notice Internal function that implements partial sort to select top vaults by delta
     * @dev Uses selection algorithm optimized for small count values (O(k*n) complexity)
     * @param vaults Array of vault addresses
     * @param deltas Array of allocation deltas (under/over allocations)
     * @param count Number of top vaults to select
     * @return selectedVaults Array of selected vault addresses
     * @return selectedIndices Array of indices of selected vaults in original array
     */
    function _selectTopVaultsByDelta(
        address[] memory vaults,
        uint256[] memory deltas,
        uint256 count
    ) private pure returns (address[] memory selectedVaults, uint256[] memory selectedIndices) {
        // Create working array of vault data
        VaultData[] memory vaultData = new VaultData[](vaults.length);
        for (uint256 i = 0; i < vaults.length; i++) {
            vaultData[i] = VaultData({ vault: vaults[i], delta: deltas[i], originalIndex: i });
        }

        // Perform partial sort using selection algorithm
        // For each position in the top count, find the maximum in remaining array
        for (uint256 pos = 0; pos < count; pos++) {
            uint256 maxIndex = pos;
            uint256 maxDelta = vaultData[pos].delta;

            // Find the vault with maximum delta in remaining unsorted portion
            for (uint256 i = pos + 1; i < vaultData.length; i++) {
                if (
                    vaultData[i].delta > maxDelta ||
                    (vaultData[i].delta == maxDelta && vaultData[i].originalIndex < vaultData[maxIndex].originalIndex)
                ) {
                    maxIndex = i;
                    maxDelta = vaultData[i].delta;
                }
            }

            // Swap maximum element to current position
            if (maxIndex != pos) {
                VaultData memory temp = vaultData[pos];
                vaultData[pos] = vaultData[maxIndex];
                vaultData[maxIndex] = temp;
            }
        }

        // Extract results from sorted portion
        selectedVaults = new address[](count);
        selectedIndices = new uint256[](count);

        for (uint256 i = 0; i < count; i++) {
            selectedVaults[i] = vaultData[i].vault;
            selectedIndices[i] = vaultData[i].originalIndex;
        }

        return (selectedVaults, selectedIndices);
    }
}

contracts/vaults/dstake/rewards/DStakeRe.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { RewardClaimable } from "../../rewards_claimable/RewardClaimable.sol";
import { DStakeRouterV2 } from "../DStakeRouterV2.sol";
import { IDStakeCollateralVaultV2 } from "../interfaces/IDStakeCollateralVaultV2.sol";
import { IDStableConversionAdapterV2 } from "../interfaces/IDStableConversionAdapterV2.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";

/**
 * @title IUniversalRewardsDistributor
 * @notice Interface for Morpho's Universal Rewards Distributor
 */
interface IUniversalRewardsDistributor {
    function claim(
        address account,
        address reward,
        uint256 claimable,
        bytes32[] calldata proof
    ) external returns (uint256);

    function claimed(address account, address reward) external view returns (uint256);

    function root() external view returns (bytes32);
}

/**
 * @title IMetaMorpho
 * @notice Extended MetaMorpho interface with reward skimming functionality
 */
interface IMetaMorpho is IERC4626 {
    function skim(address token) external;
    function setSkimRecipient(address newSkimRecipient) external;
    function skimRecipient() external view returns (address);
}

/**
 * @title DStakeRewardManagerMetaMorpho
 * @notice Manages claiming of rewards from MetaMorpho vaults through the Universal Rewards Distributor
 *         and compounds dStable into the DStakeCollateralVaultV2.
 * @dev Implements the RewardClaimable interface.
 *
 *      MetaMorpho reward flow:
 *      1. Rewards accumulate in MetaMorpho vault from underlying Morpho Blue markets
 *      2. Anyone can call skim() to transfer rewards to the skimRecipient (URD)
 *      3. URD computes Merkle trees off-chain for fair distribution
 *      4. Users claim rewards via Merkle proofs
 *      5. This contract automates the claiming and compounding process
 *
 *      Note: Unlike dLEND which has on-chain reward accrual, MetaMorpho relies on
 *      off-chain computation and API integration for reward distribution.
 */
contract DStakeRewardManagerMetaMorpho is RewardClaimable {
    using SafeERC20 for IERC20;

    // --- State ---
    address public immutable dStakeCollateralVault;
    DStakeRouterV2 public immutable dStakeRouter;
    IMetaMorpho public immutable metaMorphoVault;
    IUniversalRewardsDistributor public urd; // Can be updated by admin

    // Reward claim data (updated off-chain via API)
    struct ClaimData {
        address rewardToken;
        uint256 claimableAmount;
        bytes32[] proof;
    }

    // --- Events ---
    event URDUpdated(address oldURD, address newURD);
    event RewardsSkimmed(address indexed token, uint256 amount);
    event RewardsClaimed(address indexed token, uint256 amount);
    event ExchangeAssetProcessed(
        address indexed strategyShare,
        uint256 strategyShareAmount,
        uint256 dStableCompoundedAmount
    );
    event EmergencyWithdraw(address indexed token, uint256 amount, address indexed recipient);

    // --- Errors ---
    error InvalidRouter();
    error InvalidAdapter(address adapter);
    error AdapterReturnedUnexpectedAsset(address expected, address actual);
    error InsufficientAssetsReceived(uint256 expected, uint256 actual);
    error DefaultDepositAssetNotSet();
    error AdapterNotSetForDefaultAsset();
    error InvalidURD();
    error ClaimFailed(address token);
    error SkimRecipientMismatch();
    error ZeroAddress();

    // --- Constructor ---
    constructor(
        address _dStakeCollateralVault,
        address _dStakeRouter,
        address _metaMorphoVault,
        address _urd,
        address _treasury,
        uint256 _maxTreasuryFeeBps,
        uint256 _initialTreasuryFeeBps,
        uint256 _initialExchangeThreshold
    )
        RewardClaimable(
            IDStakeCollateralVaultV2(_dStakeCollateralVault).dStable(), // exchangeAsset is dStable
            _treasury,
            _maxTreasuryFeeBps,
            _initialTreasuryFeeBps,
            _initialExchangeThreshold
        )
    {
        if (_dStakeCollateralVault == address(0) || _dStakeRouter == address(0) || _metaMorphoVault == address(0)) {
            revert ZeroAddress();
        }
        if (exchangeAsset == address(0)) {
            revert InvalidRouter();
        }

        dStakeCollateralVault = _dStakeCollateralVault;
        dStakeRouter = DStakeRouterV2(_dStakeRouter);
        metaMorphoVault = IMetaMorpho(_metaMorphoVault);

        if (_urd != address(0)) {
            urd = IUniversalRewardsDistributor(_urd);
        }

        // Grant roles to deployer
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(REWARDS_MANAGER_ROLE, msg.sender);
    }

    // --- Admin Functions ---

    /**
     * @notice Updates the Universal Rewards Distributor address
     * @param newURD The new URD address (can be 0 to disable)
     */
    function setURD(address newURD) external onlyRole(REWARDS_MANAGER_ROLE) {
        // Validate URD interface if non-zero
        if (newURD != address(0)) {
            // Basic interface check - try to call a view function
            try IUniversalRewardsDistributor(newURD).root() returns (bytes32) {
                // Interface check passed
            } catch {
                revert InvalidURD();
            }
        }

        address oldURD = address(urd);
        urd = newURD == address(0) ? IUniversalRewardsDistributor(address(0)) : IUniversalRewardsDistributor(newURD);
        emit URDUpdated(oldURD, newURD);
    }

    /**
     * @notice Sets this contract as the skim recipient for the MetaMorpho vault
     * @dev Only needed if rewards should flow through this contract first
     */
    function becomeSkimRecipient() external onlyRole(REWARDS_MANAGER_ROLE) {
        metaMorphoVault.setSkimRecipient(address(this));
    }

    // --- Reward Management Functions ---

    /**
     * @notice Skims accumulated rewards from the MetaMorpho vault
     * @param tokens Array of reward token addresses to skim
     * @dev Restricted to REWARDS_MANAGER_ROLE to prevent griefing
     */
    function skimRewards(address[] calldata tokens) external onlyRole(REWARDS_MANAGER_ROLE) nonReentrant {
        // Cache skim recipient to save gas on multiple token skims
        address recipient = metaMorphoVault.skimRecipient();

        for (uint256 i = 0; i < tokens.length; i++) {
            uint256 balanceBefore = IERC20(tokens[i]).balanceOf(recipient);
            metaMorphoVault.skim(tokens[i]);
            uint256 balanceAfter = IERC20(tokens[i]).balanceOf(recipient);

            if (balanceAfter > balanceBefore) {
                emit RewardsSkimmed(tokens[i], balanceAfter - balanceBefore);
            }
        }
    }

    /**
     * @notice Claims rewards from the URD on behalf of the collateral vault
     * @param claimData Array of claim data including tokens, amounts, and proofs
     * @dev Claim data must be obtained from Morpho Rewards API
     * @dev Claims rewards to this contract for processing and distribution
     */
    function claimRewardsFromURD(ClaimData[] calldata claimData) external onlyRole(REWARDS_MANAGER_ROLE) {
        if (address(urd) == address(0)) {
            revert InvalidURD();
        }

        for (uint256 i = 0; i < claimData.length; i++) {
            uint256 balanceBefore = IERC20(claimData[i].rewardToken).balanceOf(address(this));

            try
                urd.claim(
                    address(this), // Claim rewards to this contract for processing
                    claimData[i].rewardToken,
                    claimData[i].claimableAmount,
                    claimData[i].proof
                )
            returns (uint256 claimed) {
                // Verify rewards were actually received
                uint256 balanceAfter = IERC20(claimData[i].rewardToken).balanceOf(address(this));
                uint256 actualReceived = balanceAfter - balanceBefore;

                if (actualReceived == 0 && claimed > 0) {
                    revert ClaimFailed(claimData[i].rewardToken);
                }

                emit RewardsClaimed(claimData[i].rewardToken, actualReceived > 0 ? actualReceived : claimed);
            } catch {
                revert ClaimFailed(claimData[i].rewardToken);
            }
        }
    }

    // --- RewardClaimable Implementation ---

    /**
     * @notice Claims specified reward tokens earned by the MetaMorpho vault
     * @param rewardTokens Array of reward token addresses to claim
     * @return actualAmounts The actual amounts claimed for each token
     */
    function _claimRewards(
        address[] calldata rewardTokens,
        address /* receiver */
    ) internal override returns (uint256[] memory actualAmounts) {
        // MetaMorpho rewards are claimed externally via URD
        // This function returns the amounts that were already claimed and are held in this contract
        // Note: receiver parameter is not used as rewards are already in this contract from URD claims

        actualAmounts = new uint256[](rewardTokens.length);

        for (uint256 i = 0; i < rewardTokens.length; i++) {
            // Check balance of reward tokens in this contract
            // These should have been claimed via claimRewardsFromURD
            actualAmounts[i] = IERC20(rewardTokens[i]).balanceOf(address(this));
        }

        return actualAmounts;
    }

    /**
     * @notice Processes the exchange asset (dStable) and compounds it into the vault
     * @param exchangeAmountIn The amount of dStable to compound
     */
    function _processExchangeAssetDeposit(uint256 exchangeAmountIn) internal override {
        // Get the router's default deposit strategy share
        address defaultStrategyShare = dStakeRouter.defaultDepositStrategyShare();
        if (defaultStrategyShare == address(0)) {
            revert DefaultDepositAssetNotSet();
        }

        // Get the adapter for the default strategy share
        address adapter = dStakeRouter.strategyShareToAdapter(defaultStrategyShare);
        if (adapter == address(0)) {
            revert AdapterNotSetForDefaultAsset();
        }

        // Approve adapter to spend dStable
        IERC20(exchangeAsset).forceApprove(adapter, exchangeAmountIn);

        // Check collateral vault balance before conversion
        uint256 balanceBefore = IERC20(defaultStrategyShare).balanceOf(dStakeCollateralVault);

        // Convert dStable to strategy share via adapter
        (address returnedStrategyShare, uint256 strategyShareAmount) = IDStableConversionAdapterV2(adapter)
            .depositIntoStrategy(exchangeAmountIn);

        // Verify the adapter returned the expected strategy share
        if (returnedStrategyShare != defaultStrategyShare) {
            revert AdapterReturnedUnexpectedAsset(defaultStrategyShare, returnedStrategyShare);
        }

        // Verify that the collateral vault actually received the expected assets
        uint256 balanceAfter = IERC20(defaultStrategyShare).balanceOf(dStakeCollateralVault);
        uint256 actualReceived = balanceAfter - balanceBefore;
        if (actualReceived < strategyShareAmount) {
            revert InsufficientAssetsReceived(strategyShareAmount, actualReceived);
        }

        // Emit event for tracking (use actualReceived for accuracy)
        emit ExchangeAssetProcessed(defaultStrategyShare, actualReceived, exchangeAmountIn);

        // Clear any remaining approval now that the transfer has completed
        IERC20(exchangeAsset).forceApprove(adapter, 0);
    }

    /**
     * @notice Emergency function to recover stuck tokens
     * @param token The token to recover
     * @param amount The amount to recover
     * @dev Only callable by admin
     */
    function emergencyWithdraw(address token, uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (treasury == address(0)) {
            revert ZeroAddress();
        }
        IERC20(token).safeTransfer(treasury, amount);
        emit EmergencyWithdraw(token, amount, treasury);
    }

    // --- View Functions ---

    /**
     * @notice Checks if the URD has been configured
     * @return True if URD is set
     */
    function isURDConfigured() external view returns (bool) {
        return address(urd) != address(0);
    }

    /**
     * @notice Gets the current skim recipient of the MetaMorpho vault
     * @return The address receiving skimmed rewards
     */
    function currentSkimRecipient() external view returns (address) {
        return metaMorphoVault.skimRecipient();
    }

    /**
     * @notice Checks how much of a reward token has been claimed by this contract
     * @param rewardToken The reward token to check
     * @return The amount already claimed
     */
    function getClaimedAmount(address rewardToken) external view returns (uint256) {
        if (address(urd) == address(0)) {
            return 0;
        }
        return urd.claimed(address(this), rewardToken);
    }
}

contracts/vaults/dstake/vaults/DStakeIdl.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { ERC4626 } from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DStakeIdleVault
 * @notice Minimal ERC4626 vault that holds idle dUSD and streams fixed-rate emissions to depositors.
 * @dev Emission tokens must be pre-funded via `fundRewards`. Pending emissions accrue linearly over
 *      `emissionPerSecond` between `emissionStart` and `emissionEnd` and are released to depositors on
 *      interaction or explicit `accrueRewards` calls. Reserves that are not yet released are excluded
 *      from the ERC4626 accounting so they do not dilute share pricing before they vest.
 */
contract DStakeIdleVault is ERC4626, AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- Roles ---
    bytes32 public constant REWARD_MANAGER_ROLE = keccak256("REWARD_MANAGER_ROLE");

    // --- Errors ---
    error ZeroAddress();
    error InvalidEmissionWindow();
    error InsufficientRewardReserve();

    // --- Events ---
    event EmissionScheduleSet(uint64 indexed start, uint64 indexed end, uint256 emissionPerSecond);
    event RewardsFunded(address indexed sender, uint256 amount);
    event RewardsWithdrawn(address indexed receiver, uint256 amount);
    event RewardsAccrued(uint256 amountReleased);

    // --- State ---
    uint64 public emissionStart; // Timestamp when emissions begin (inclusive)
    uint64 public emissionEnd; // Timestamp when emissions end (exclusive)
    uint64 public lastEmissionUpdate; // Last timestamp emissions were accounted
    uint256 public emissionPerSecond; // Amount of dUSD released per second
    uint256 public rewardReserve; // Portion of assets reserved for future emissions

    constructor(
        IERC20 asset_,
        string memory name_,
        string memory symbol_,
        address admin,
        address rewardManager
    ) ERC20(name_, symbol_) ERC4626(asset_) {
        if (address(asset_) == address(0) || admin == address(0) || rewardManager == address(0)) {
            revert ZeroAddress();
        }

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REWARD_MANAGER_ROLE, rewardManager);
        lastEmissionUpdate = uint64(block.timestamp);
    }

    // --- ERC4626 overrides ---
    function deposit(uint256 assets, address receiver) public override nonReentrant returns (uint256) {
        _accrue();
        return super.deposit(assets, receiver);
    }

    function mint(uint256 shares, address receiver) public override nonReentrant returns (uint256) {
        _accrue();
        return super.mint(shares, receiver);
    }

    function withdraw(uint256 assets, address receiver, address owner) public override nonReentrant returns (uint256) {
        _accrue();
        return super.withdraw(assets, receiver, owner);
    }

    function redeem(uint256 shares, address receiver, address owner) public override nonReentrant returns (uint256) {
        _accrue();
        return super.redeem(shares, receiver, owner);
    }

    /// @notice Total assets backing vault shares, accounting for vested emissions.
    function totalAssets() public view override returns (uint256) {
        uint256 rawAssets = IERC20(asset()).balanceOf(address(this));
        uint256 pending = _pendingEmission();
        if (rawAssets < rewardReserve) {
            return pending; // Should not happen, but prevents underflow.
        }
        return rawAssets - rewardReserve + pending;
    }

    // --- Reward Management ---

    /// @notice Pre-fund the vault with dUSD that will be streamed to depositors over time.
    /// @dev Caller must approve `amount` before invoking. Accrues existing emissions first to preserve ordering.
    function fundRewards(uint256 amount) external onlyRole(REWARD_MANAGER_ROLE) {
        if (amount == 0) {
            return;
        }
        _accrue();
        IERC20(asset()).safeTransferFrom(msg.sender, address(this), amount);
        rewardReserve += amount;
        emit RewardsFunded(msg.sender, amount);
    }

    /// @notice Withdraw unreleased reward reserves back to the reward manager.
    function withdrawUnreleasedRewards(address to, uint256 amount) external onlyRole(REWARD_MANAGER_ROLE) {
        if (to == address(0)) {
            revert ZeroAddress();
        }
        _accrue();
        if (amount > rewardReserve) {
            revert InsufficientRewardReserve();
        }
        rewardReserve -= amount;
        IERC20(asset()).safeTransfer(to, amount);
        emit RewardsWithdrawn(to, amount);
    }

    /// @notice Configure the emission schedule for streaming rewards.
    /// @param start Timestamp when emissions start (inclusive)
    /// @param end Timestamp when emissions end (exclusive)
    /// @param rate Emission rate in dUSD per second
    function setEmissionSchedule(uint64 start, uint64 end, uint256 rate) external onlyRole(REWARD_MANAGER_ROLE) {
        if (end != 0 && end <= start) {
            revert InvalidEmissionWindow();
        }
        _accrue();

        emissionStart = start;
        emissionEnd = end;
        emissionPerSecond = rate;
        lastEmissionUpdate = uint64(block.timestamp);

        emit EmissionScheduleSet(start, end, rate);
    }

    /// @notice Manually accrue any pending emissions into the vault shares.
    /// @return amountReleased Amount of dUSD moved from the reward reserve into active assets.
    function accrueRewards() external returns (uint256 amountReleased) {
        amountReleased = _accrue();
        emit RewardsAccrued(amountReleased);
    }

    /// @notice Amount of rewards that have vested but not yet been accounted for.
    function pendingEmission() external view returns (uint256) {
        return _pendingEmission();
    }

    /// @notice Remaining reserves earmarked for future emissions (excludes pending amount).
    function remainingRewardReserve() external view returns (uint256) {
        uint256 pending = _pendingEmission();
        if (pending >= rewardReserve) {
            return 0;
        }
        return rewardReserve - pending;
    }

    // --- Internal helpers ---

    function _accrue() internal returns (uint256 released) {
        // NOTE: Known limitation – when totalSupply() is zero accrued rewards are released into
        // the vault and remain claimable by the next depositor. Operationally we rely on the vault
        // maintaining a non-zero supply or keeping reward funding paused during idle periods.
        released = _pendingEmission();
        if (released == 0) {
            lastEmissionUpdate = uint64(block.timestamp);
            return 0;
        }
        rewardReserve -= released;
        lastEmissionUpdate = uint64(block.timestamp);
    }

    function _pendingEmission() internal view returns (uint256) {
        uint64 currentTime = uint64(block.timestamp);
        uint64 lastUpdate = lastEmissionUpdate;

        if (currentTime <= lastUpdate) {
            return 0;
        }

        uint64 start = emissionStart;
        uint64 end = emissionEnd;
        if (end != 0 && lastUpdate >= end) {
            return 0;
        }

        uint64 effectiveStart = start > lastUpdate ? start : lastUpdate;
        if (end != 0 && end < currentTime) {
            currentTime = end;
        }

        if (currentTime <= effectiveStart) {
            return 0;
        }

        uint256 elapsed = uint256(currentTime - effectiveStart);
        uint256 accrued = elapsed * emissionPerSecond;
        if (accrued > rewardReserve) {
            return rewardReserve;
        }
        return accrued;
    }
}

